import json, os, glob, re
from datetime import datetime

def extract_text(o):
  msg=o.get('message') or {}
  content=msg.get('content')
  texts=[]
  if isinstance(content,str): texts.append(content)
  elif isinstance(content,list):
    for c in content:
      if isinstance(c,dict):
        if c.get('type') in ('text','input_text','output_text') and c.get('text'):
          texts.append(c['text'])
        elif c.get('type')=='tool_use' and c.get('name'):
          texts.append(f"[tool:{c.get('name')}]")
      elif isinstance(c,str): texts.append(c)
  return '\n'.join(texts)

# focus transcripts likely from today work (not daily report wake itself)
cands=[]
for p in glob.glob('/Users/mac/.dc-platform/memory/mirrors/agent-transcripts/**/*.jsonl', recursive=True)+glob.glob('/Users/mac/.cursor/projects/Users-mac-Desktop-CHcode/agent-transcripts/*/*.jsonl'):
  mt=datetime.fromtimestamp(os.path.getmtime(p))
